const DEFAULT={name:"",phone:"",remindersEnabled:true,reminderCount:3,times:["09:00","13:00","19:30"],avoidRepeats:true,customMessages:"",sent:[],used:[],deviceId:""};
let state={...DEFAULT,...load()},category="Sweet & Romantic",currentMessage="";

function load(){try{return JSON.parse(localStorage.getItem("dearlyState")||"{}")}catch{return {}}}
function save(){localStorage.setItem("dearlyState",JSON.stringify(state))}
function $(id){return document.getElementById(id)}
function toast(t){const e=$("toast");e.textContent=t;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),1800)}
function formatTime(t){let[h,m]=t.split(":").map(Number),ap=h>=12?"PM":"AM";h=h%12||12;return `${h}:${String(m).padStart(2,"0")} ${ap}`}
function allMessages(){return Object.values(CATEGORIES).flat().concat((state.customMessages||"").split(/\n/).map(x=>x.trim()).filter(Boolean))}
function pickMessage(){let pool=category==="All"?allMessages():[...(CATEGORIES[category]||CATEGORIES["Sweet & Romantic"])];if(state.avoidRepeats){const fresh=pool.filter(x=>!(state.used||[]).includes(x));if(fresh.length)pool=fresh}currentMessage=pool[Math.floor(Math.random()*pool.length)]||"I love you. ❤️";state.used=[...(state.used||[]),currentMessage].slice(-100);save();renderMessage()}
function renderMessage(){$("message").textContent=currentMessage;$("categoryLabel").textContent=category}
function renderChips(){$("categoryChips").innerHTML=["All",...CATEGORIES.All].map(c=>`<button class="chip ${c===category?"active":""}" data-cat="${c}">${c}</button>`).join("");document.querySelectorAll(".chip").forEach(b=>b.onclick=()=>{category=b.dataset.cat;renderChips();pickMessage()})}
function renderStats(){const today=new Date().toISOString().slice(0,10),sent=(state.sent||[]),n=sent.filter(x=>x.date===today).length;$("sentToday").textContent=n;$("totalSent").textContent=sent.length;let streak=0,d=new Date();for(const date of [...new Set(sent.map(x=>x.date))].sort().reverse()){const ds=d.toISOString().slice(0,10);if(date===ds){streak++;d.setDate(d.getDate()-1)}else if(date<ds)break}$("streak").textContent=streak}
function renderReminderSummary(){const n=Number(state.reminderCount)||1;$("reminderSummary").textContent=`${n} reminder${n===1?"":"s"} a day`;$("reminderTimes").textContent=(state.times||[]).slice(0,n).map(formatTime).join(" · ")}
function render(){const has=!!state.name&&!!state.phone;$("setupView").classList.toggle("hidden",has);$("homeView").classList.toggle("hidden",!has);$("settingsView").classList.add("hidden");$("recipientName").textContent=state.name||"her";$("avatar").textContent=(state.name||"♡").charAt(0).toUpperCase();renderChips();renderStats();renderReminderSummary();if(!currentMessage)pickMessage()}
function openSettings(){$("homeView").classList.add("hidden");$("setupView").classList.add("hidden");$("settingsView").classList.remove("hidden");$("settingsName").value=state.name;$("settingsPhone").value=state.phone;$("remindersEnabled").checked=state.remindersEnabled;$("avoidRepeats").checked=state.avoidRepeats;$("reminderCount").innerHTML=Array.from({length:10},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join("");$("reminderCount").value=state.reminderCount;$("customMessages").value=state.customMessages||"";renderTimeFields();updatePushStatus()}
function renderTimeFields(){const n=Number($("reminderCount").value||state.reminderCount||3);state.times=state.times||[];while(state.times.length<n)state.times.push("09:00");$("timeFields").innerHTML=Array.from({length:n},(_,i)=>`<label>Reminder ${i+1}<input class="time-input" data-i="${i}" type="time" value="${state.times[i]||"09:00"}"></label>`).join("")}
function saveSetup(){const name=$("setupName").value.trim(),phone=$("setupPhone").value.trim();if(!name||!phone)return toast("Please enter her name and phone number.");state.name=name;state.phone=phone;if(!state.deviceId)state.deviceId=crypto.randomUUID();save();render();toast("You're all set ❤️");}
function saveSettings(){state.name=$("settingsName").value.trim();state.phone=$("settingsPhone").value.trim();state.remindersEnabled=$("remindersEnabled").checked;state.reminderCount=Number($("reminderCount").value);state.times=[...document.querySelectorAll(".time-input")].map(x=>x.value||"09:00");state.avoidRepeats=$("avoidRepeats").checked;state.customMessages=$("customMessages").value;if(!state.deviceId)state.deviceId=crypto.randomUUID();save();render();toast("Settings saved.");}
function textHer(){if(!state.phone)return toast("Add her phone number in Settings.");state.sent.push({date:new Date().toISOString().slice(0,10),message:currentMessage,at:new Date().toISOString()});save();renderStats();window.location.href=`sms:${state.phone}?&body=${encodeURIComponent(currentMessage)}`;}
async function copyMessage(){try{await navigator.clipboard.writeText(currentMessage);toast("Message copied.")}catch{toast("Copy isn't available here.")}}
function urlBase64ToUint8Array(base64String){const padding="=".repeat((4-base64String.length%4)%4),base64=(base64String+padding).replace(/-/g,"+").replace(/_/g,"/"),raw=atob(base64);return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)))}
async function registerPush(){if(!("serviceWorker" in navigator)||!("PushManager" in window)||!("Notification" in window))throw new Error("Push notifications are not supported by this browser.");if(!window.matchMedia("(display-mode: standalone)").matches&&!navigator.standalone){toast("On iPhone, add Dearly to your Home Screen first.");return}const permission=await Notification.requestPermission();if(permission!=="granted"){toast("Notifications were not allowed.");return}const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(VAPID_PUBLIC_KEY)});if(!state.deviceId)state.deviceId=crypto.randomUUID();const payload={device_id:state.deviceId,wife_name:state.name,phone:state.phone,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||"America/Detroit",reminder_times:state.times.slice(0,state.reminderCount),reminders_enabled:state.remindersEnabled,push_subscription:sub.toJSON()};const r=await fetch(`${SUPABASE_URL}/rest/v1/dearly_devices?on_conflict=device_id`,{method:"POST",headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,"Content-Type":"application/json",Prefer:"resolution=merge-duplicates,return=minimal"},body:JSON.stringify(payload)});if(!r.ok)throw new Error("Could not save the push subscription ("+r.status+")");save();toast("Background notifications are enabled ❤️");updatePushStatus()}
async function updatePushStatus(){const e=$("pushStatus");if(!("Notification" in window)){e.textContent="This browser does not support notifications.";return}e.textContent=Notification.permission==="granted"?"Push permission is enabled on this iPhone.":"Push permission has not been granted yet."}
$("saveSetup").onclick=saveSetup;$("settingsBtn").onclick=openSettings;$("backBtn").onclick=render;$("editRecipient").onclick=openSettings;$("newMessage").onclick=pickMessage;$("textHer").onclick=textHer;$("copyMessage").onclick=copyMessage;$("saveSettings").onclick=saveSettings;$("notificationBtn").onclick=registerPush;$("requestNotifications").onclick=registerPush;$("reminderCount").onchange=renderTimeFields;
if("serviceWorker" in navigator)navigator.serviceWorker.register("./service-worker.js").catch(console.error);
render();updatePushStatus();